    {
      "id": "2",
      "type": "CONST",
      "text": "The initial hash value uses the constant 0x1505.",
      "asserted_values": ["0x1505"],
      "confidence": 1.0
    },
    {
      "id": "3",
      "type": "IO",
      "text": "Returns 0x1505 when the input length is 0.",
      "asserted_values": ["0x1505"],
      "confidence": 1.0,
      "io": {
        "when": "param_2 == 0",
        "returns": "0x1505"
      }
    },
    {
      "id": "4",
      "type": "IO",
      "text": "Returns the computed hash value when the input length is greater than 0.",
      "asserted_values": [],
      "confidence": 1.0,
      "io": {
        "when": "param_2 > 0",
        "returns": "computed hash value"
      }
    },
    {
      "id": "5",
      "type": "SIDE",
      "text": "Does not write to out.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "6",
      "type": "CF",
      "text": "Uses a loop to iterate over the input data.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_04(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len != 0) {\n    uint64_t hash = 0x1505;\n    for (size_t i = 0; i < len; i++) {\n      hash = hash * 0x21 + in[i];\n    }\n    return hash;\n  }\n  return 0x1505;\n}"
}
